import re
import tanium
import fs
import os

results = tanium.sensor_results()

def expand_user_dirs(file_path):
    u_prof = r"%userprofile%|^~|^\$HOME"
    u_prof_tag = re.search(u_prof, file_path, flags=re.FLAG_IGNORE_CASE)
    if u_prof_tag != None:
        try:
            query_results = tanium.query_sql("select home_dir from system.users")
        except:
            return [], u_prof_tag.group(0)
        return [str(c["home_dir"]) for c in query_results if c["home_dir"]], u_prof_tag.group(0)
    return [file_path], None

def _check_file(path):
    if not path or not fs.exists(path) or fs.is_directory(path):
        return False
    return True

def main():
    file_path = tanium.decode_parameter("||file||")
    user_dirs, u_prof_tag = expand_user_dirs(file_path)
    if u_prof_tag and len(user_dirs) == 0:
        results.add("File does not exist")
        return
    if not u_prof_tag:
        path = os.expand_environment_strings(file_path)
        if fs.check_autofs(path):
            results.add("File does not exist")
            return
        if _check_file(path):
            results.add("File Exists: {}".format(path))
        else:
            results.add("File does not exist")
        return
    found = False
    for user_dir in user_dirs:
        if len(results) >= 1000:
            results.add("Warning: Maximum number of output lines (100) reached")
            break
        suffix = os.expand_environment_strings(file_path[len(u_prof_tag):])
        if os.platform == os.PLATFORM_WINDOWS:
            suffix = suffix.lower()
        full_path = user_dir + suffix
        if fs.check_autofs(full_path):
            continue
        if not _check_file(full_path):
            continue
        found = True
        results.add("File Exists: {}".format(full_path))

    if not found:
        results.add("File does not exist")

